    l0_coefficient: float = 3e-4
    l0_warm_up_steps: int = 0
    pre_act_loss_coefficient: float = 3e-6

    @override
    @classmethod
    def architecture(cls) -> str:
        return "jumprelu_matryoshka"

    @classmethod
    def from_dict(cls, cfg: dict, total_steps: int = 0) -> "JumpReLUMatryoshkaConfig":
        d_sae = int(cfg.get("d_sae", 4096))
        default_widths = [128, 512, 2048, d_sae]
        widths = list(cfg.get("matryoshka_widths", default_widths))
        if widths[-1] != d_sae:
            widths.append(d_sae)
        return cls(
            d_in=D_IN,
            d_sae=d_sae,
            matryoshka_widths=widths,
            use_freq_sort=cfg.get("use_freq_sort", True),
            term_tilt=float(cfg.get("term_tilt", 0.0)),
            inner_loss_weight=float(cfg.get("inner_loss_weight", 1.0)),
            jumprelu_init_threshold=float(cfg.get("jumprelu_init_threshold", 0.01)),
            jumprelu_bandwidth=float(cfg.get("jumprelu_bandwidth", 0.05)),
            jumprelu_sparsity_loss_mode=cfg.get("jumprelu_sparsity_loss_mode", "tanh"),
            jumprelu_tanh_scale=float(cfg.get("jumprelu_tanh_scale", 4.0)),
            l0_coefficient=float(cfg.get("l0_coefficient", 3e-4)),
            l0_warm_up_steps=int(cfg.get("l0_warm_up_steps", 0)),
            pre_act_loss_coefficient=float(cfg.get("pre_act_loss_coefficient", 3e-6)),
            dtype="float32",
            device="cuda",
        )


class JumpReLUMatryoshka(TrainingSAE):
    """JumpReLU adaptive-threshold sparsity + freq-sorted Matryoshka nested decode."""

    cfg: JumpReLUMatryoshkaConfig
    b_enc: nn.Parameter
    log_threshold: nn.Parameter

    def __init__(self, cfg: JumpReLUMatryoshkaConfig, use_error_term: bool = False):
        super().__init__(cfg, use_error_term)
        self.bandwidth = cfg.jumprelu_bandwidth
        if cfg.use_freq_sort:
            self.freq_tracker = FiringFreqTracker(cfg.d_sae, device=cfg.device)
        else:
            self.freq_tracker = None

    @override
    def initialize_weights(self) -> None:
        super().initialize_weights()
        self.b_enc = nn.Parameter(
            torch.zeros(self.cfg.d_sae, dtype=self.dtype, device=self.device)
        )
        self.log_threshold = nn.Parameter(
            torch.ones(self.cfg.d_sae, dtype=self.dtype, device=self.device)
            * math.log(self.cfg.jumprelu_init_threshold)
        )

    @property
    def threshold(self) -> torch.Tensor:
        return torch.exp(self.log_threshold)

    @override
    def encode_with_hidden_pre(self, x: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor]:
        sae_in = self.process_sae_in(x)
        hidden_pre = self.hook_sae_acts_pre(sae_in @ self.W_enc + self.b_enc)
        feature_acts = _JumpReLUFn.apply(hidden_pre, self.threshold, self.bandwidth)
        feature_acts = self.hook_sae_acts_post(feature_acts)
        return feature_acts, hidden_pre

    def _freq_sorted_iterable_decode(self, feature_acts: torch.Tensor):
        """Decode with frequency-sorted index mapping for Matryoshka (detached, like ReferenceStyleSAE)."""
        sorted_indices = None
        if self.freq_tracker is not None:
            sorted_indices = self.freq_tracker.frequencies.argsort(descending=True)

        decoded = self.b_dec
        prev_portion = 0
        widths = self.cfg.matryoshka_widths[:-1]

        for width in widths:
            if sorted_indices is not None:
                idx = sorted_indices[prev_portion:width]
                current_delta = feature_acts[:, idx] @ self.W_dec[idx]
            else:
                current_delta = feature_acts[:, prev_portion:width] @ self.W_dec[prev_portion:width]
            decoded = decoded.detach() + current_delta
            prev_portion = width
            yield width, self.run_time_activation_norm_fn_out(decoded)

    def _term_mean(self, per_sample_loss: torch.Tensor) -> torch.Tensor:
        t = self.cfg.term_tilt
        if t <= 0:
            return per_sample_loss.mean()
        weights = torch.softmax(
            per_sample_loss.detach() * t / per_sample_loss.detach().mean(), dim=0
        )
        return (weights * per_sample_loss).sum()

    @override
    def calculate_aux_loss(self, step_input, feature_acts, hidden_pre, sae_out):
        threshold = self.threshold
        W_dec_norm = self.W_dec.norm(dim=1)

        if self.cfg.jumprelu_sparsity_loss_mode == "step":
            l0 = torch.sum(_StepFn.apply(hidden_pre, threshold, self.bandwidth), dim=-1)
            l0_loss = (step_input.coefficients["l0"] * l0).mean()
        else:  # tanh
            per_item_l0_loss = torch.tanh(
                self.cfg.jumprelu_tanh_scale * feature_acts * W_dec_norm
            ).sum(dim=-1)
            l0_loss = (step_input.coefficients["l0"] * per_item_l0_loss).mean()

        losses = {"l0_loss": l0_loss}

        if self.cfg.pre_act_loss_coefficient is not None and step_input.dead_neuron_mask is not None:
            if step_input.dead_neuron_mask.any():
                per_item_loss = (
                    (threshold - hidden_pre).relu() * step_input.dead_neuron_mask * W_dec_norm
                ).sum(dim=-1)
                losses["pre_act_loss"] = self.cfg.pre_act_loss_coefficient * per_item_loss.mean()

        if self.freq_tracker is not None:
            self.freq_tracker.update(feature_acts)

        for width, inner_recon in self._freq_sorted_iterable_decode(feature_acts):
            inner_per_sample = self.mse_loss_fn(inner_recon, step_input.sae_in).sum(dim=-1)
            inner_loss = self._term_mean(inner_per_sample) * self.cfg.inner_loss_weight
            losses[f"inner_mse_loss_{width}"] = inner_loss

        return losses

    @override
    def get_coefficients(self):
        return {
            "l0": TrainCoefficientConfig(
                value=self.cfg.l0_coefficient,
                warm_up_steps=self.cfg.l0_warm_up_steps,
            ),
        }
